// Copies runtime assets into public/ (generated, git-ignored):
//   public/wasm/web-ifc.wasm                       - web-ifc runtime (IFC parser + 3D viewer)
//   public/samples/simple-frame.json               - ModelInput fixture (data/)
//   public/samples/Building-Structural-IFC4.ifc    - IFC fixture (data/)
//   public/samples/{model_rev1,model_rev2}.ifc,
//   public/samples/calc_package.pdf,
//   public/samples/calc_supplement.pdf             - the synthetic sample ("Load sample"), generated by
//                                                    tools/calcgraph-reference (generated, not committed)
//   public/samples/demo/harborview-*.json          - Noah's legacy A/B diff demo (data/)
// Runs on postinstall / predev / prebuild (and `npm run assets`). The REQUIRED assets (web-ifc.wasm and
// the tracked fixtures, the first block below) fail predev / prebuild / assets with exit 1, so a build
// can never ship without the IFC runtime; on postinstall they only warn, so an install can finish and
// be repaired. The synthetic sample is optional everywhere: a missing one is reported here and in the
// app ("sample not generated").
import { copyFileSync, existsSync, mkdirSync, statSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const require = createRequire(join(repoRoot, "packages/ifc-parser/package.json"));

let wasm;
try {
  wasm = join(dirname(require.resolve("web-ifc/package.json")), "web-ifc.wasm");
} catch {
  wasm = join(repoRoot, "node_modules/web-ifc/web-ifc.wasm");
}

// synth.generate writes to data/synthetic by default; an --out data run is accepted too
const synthetic = ["data/synthetic", "data"]
  .map((d) => join(repoRoot, "tools/calcgraph-reference", d))
  .find((d) => existsSync(join(d, "model_rev1.ifc"))) ?? join(repoRoot, "tools/calcgraph-reference/data/synthetic");
const copies = [
  [wasm, "public/wasm/web-ifc.wasm"],
  [join(repoRoot, "data/simple-frame.json"), "public/samples/simple-frame.json"],
  [join(repoRoot, "data/Building-Structural-IFC4.ifc"), "public/samples/Building-Structural-IFC4.ifc"],
  [join(repoRoot, "data/harborview-tower-rev1-base.json"), "public/samples/demo/harborview-tower-rev1-base.json"],
  [join(repoRoot, "data/harborview-tower-rev2-compare.json"), "public/samples/demo/harborview-tower-rev2-compare.json"],
];
const sample = ["model_rev1.ifc", "model_rev2.ifc", "calc_package.pdf", "calc_supplement.pdf"].map((f) => [join(synthetic, f), `public/samples/${f}`]);

function copy(from, rel) {
  const to = join(repoRoot, rel);
  mkdirSync(dirname(to), { recursive: true });
  if (existsSync(to) && statSync(to).size === statSync(from).size && statSync(to).mtimeMs >= statSync(from).mtimeMs) return;
  copyFileSync(from, to);
  console.log(`[assets] ${rel}`);
}

const missingRequired = copies.filter(([from]) => !existsSync(from));
for (const [from, rel] of copies) if (existsSync(from)) copy(from, rel);
if (missingRequired.length) {
  const list = missingRequired.map(([from]) => `  ${from}`).join("\n");
  if (process.env.npm_lifecycle_event === "postinstall") {
    console.warn(`[assets] WARNING: required asset(s) missing - dev and build will fail until fixed:\n${list}`);
  } else {
    console.error(`[assets] required asset(s) missing (run npm ci at the repo root):\n${list}`);
    process.exitCode = 1;
  }
}

const missing = sample.filter(([from]) => !existsSync(from));
if (missing.length) {
  console.warn(
    `[assets] synthetic sample not generated (${missing.map(([f]) => f.split("/").pop()).join(", ")} missing): ` +
      `"Load sample" will say so. Generate it with: cd tools/calcgraph-reference && uv run python -m synth.generate, then npm run assets`,
  );
} else {
  for (const [from, rel] of sample) copy(from, rel);
}
